// Package mellifera_test holds the golden end-to-end integration test for the
// scan-library vertical slice. It is a pure black-box driver: it builds the real
// server + base-scanner binaries, starts the server on a temp SQLite DB and a
// random free port, and drives the three HTTP endpoints with a real client. The
// base-scanner runs as a REAL subprocess via go-plugin (architecture §0
// principle 2 — subprocess isolation) and probes the fixture files with REAL
// ffprobe. This is the foundational proof that the whole plugin-subprocess
// pipeline — api → module → plugin manager → base-scanner subprocess → ffprobe
// → store → list — is wired correctly (acceptance.md AC-1; integration_map.md
// seam S-integration; jointly validates S1..S11).
//
// The test skips cleanly under `go test -short` and when ffprobe/ffmpeg are not
// on PATH (INV4: never fail CI for a missing optional binary). With both on PATH
// (the project toolchain guarantees them) it runs the full golden path and must
// pass under `go test ./...` by default.
package itest

import (
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"
)

// HTTP + lifecycle timeouts for the integration harness. The scan POST is
// synchronous (the api scan handler blocks on scan.Run), so the client timeout
// must cover a full walk + ffprobe-of-every-file + identify + persist cycle.
const (
	readinessDial = 15 * time.Second // how long to wait for the server to answer
	httpTimeout   = 60 * time.Second // per-request client timeout (covers the scan)
	probeInterval = 100 * time.Millisecond
	shutdownGrace = 10 * time.Second // SIGINT-then-SIGKILL fallback window
)

// TestIntegrationScanLibrary is THE golden test for AC-1: it builds the real
// base-scanner + server binaries, starts the server against a temp SQLite DB and
// a fixture TV library, scans it through the real subprocess + real ffprobe, and
// asserts the persisted items carry media-type-agnostic BASE parsed fields
// (relative_path/extension) plus a real ffprobe blob. base-scanner no longer
// emits TV-specific fields (the parseTV extraction, Task 06/07); the TV parse is
// produced by the tv-parser plugin and re-asserted end-to-end by the Task 11
// pipeline golden. This test also covers AC-4 (escaping symlink rejected), AC-6
// (unprobeable file soft-fails + scan completes), and re-scan idempotency.
func TestIntegrationScanLibrary(t *testing.T) {
	if testing.Short() {
		t.Skip("integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping AC-1 golden (INV4); the identification slice is independently proven by the base-scanner contract tests")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixture AC-1 requires")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "mellifera-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "tv-parser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "image-enricher", "./plugins/image-enricher")
	fixtureRoot := writeFixtures(t)

	token := "test-admin-token-integration"
	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, token)
	client := &http.Client{Timeout: httpTimeout}

	libID := createLibrary(t, client, baseURL, token, fixtureRoot)

	first := scanLibrary(t, client, baseURL, token, libID)
	if first.Discovered != 4 {
		t.Fatalf("scan discovered = %d, want 4 (3 media + bad.mkv; escape symlink skipped)", first.Discovered)
	}
	if first.Persisted != 4 {
		t.Fatalf("scan persisted = %d, want 4", first.Persisted)
	}
	if !scanWarnedAboutFfprobe(first.Warnings) {
		t.Fatalf("scan warnings = %v, want at least one ffprobe soft-fail entry (AC-6)", first.Warnings)
	}

	byRel := indexByPath(t, listItems(t, client, baseURL, token, libID))
	assertParsedItems(t, byRel)
	assertSoftFailItem(t, byRel, "bad.mkv")
	assertEscapeSkipped(t, byRel, "escape.mkv")
	assertAC1FfprobeBlobs(t, byRel)

	// B9: re-scan is idempotent — PutItem upserts by file_id, so no duplicates.
	second := scanLibrary(t, client, baseURL, token, libID)
	if second.Persisted != first.Persisted {
		t.Fatalf("re-scan persisted = %d, want %d (idempotent upsert)", second.Persisted, first.Persisted)
	}
	if got := len(listItems(t, client, baseURL, token, libID)); got != len(byRel) {
		t.Fatalf("re-scan changed item count: %d -> %d (expected idempotent)", len(byRel), got)
	}
}

// buildBinary compiles one Go binary into tmp and returns its path. The build
// runs from the module root (resolved via `go list -m`) so it is robust to the
// test's own working directory.
func buildBinary(t *testing.T, tmp, name, pkg string) string {
	t.Helper()
	out := filepath.Join(tmp, name)
	build := exec.Command("go", "build", "-o", out, pkg)
	build.Dir = moduleRoot(t)
	if err := build.Run(); err != nil {
		t.Fatalf("go build %s: %v", pkg, err)
	}
	return out
}

// moduleRoot returns the Go module root (the directory holding go.mod).
func moduleRoot(t *testing.T) string {
	t.Helper()
	out, err := exec.Command("go", "list", "-m", "-f", "{{.Dir}}").Output()
	if err != nil {
		t.Fatalf("go list -m: %v", err)
	}
	return strings.TrimSpace(string(out))
}

// serialPluginBins builds the three serial-suite plugin binaries into tmp and
// returns them as the env values for MELLIFERA_SERIAL_SCANNER, MELLIFERA_SERIAL_PARSER
// and MELLIFERA_FRAME_GRABBER. The registry seeds all six modules, so EVERY full
// server start launches every serial plugin at startup — pinning absolute tmp
// paths keeps the harness HERMETIC: without them the plugins fall back to the
// repo-relative bin/ defaults, which only resolve when the tests happen to run
// from the module root with bin/ populated by `make build-plugin`.
func serialPluginBins(t *testing.T, tmp string) (scanner, parser, grabber string) {
	t.Helper()
	return buildBinary(t, tmp, "itest-serial-scanner", "./plugins/serial-scanner"),
		buildBinary(t, tmp, "itest-serial-parser", "./plugins/serial-parser"),
		buildBinary(t, tmp, "itest-frame-grabber", "./plugins/frame-grabber")
}

// shikimoriBin builds the shikimori metadata plugin once per tmp and returns
// its path. The server loads it beside the other metadata plugins
// (MELLIFERA_SHIKIMORI, enrichment) — a launch without the env fatals on the
// repo-relative bin/ default, so every server-start helper pins it.
func shikimoriBin(t *testing.T, tmp string) string {
	t.Helper()
	return buildBinary(t, tmp, "itest-shikimori", "./plugins/shikimori")
}

// writeFixtures builds the TV fixture tree under a temp dir and returns its root.
// Three real (ffmpeg-generated) media files exercise TV parsing, the Cyrillic
// path, and resolution/release-group stripping; one zero-byte file drives the
// AC-6 soft-fail path; one symlink escaping the root proves AC-4.
func writeFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()

	nested := filepath.Join(root, "Breaking Bad", "Season 1")
	mustMkdir(t, nested)
	makeMedia(t, filepath.Join(nested, "Breaking Bad S01E01.mkv"))
	makeMedia(t, filepath.Join(root, "Breaking Bad S01E02 1080p-EXAMPLE.mkv"))
	makeMedia(t, filepath.Join(root, "Игра престолов S01E01.mkv"))
	mustWrite(t, filepath.Join(root, "bad.mkv"), nil) // zero-byte -> AC-6 soft-fail

	// AC-4: a symlink whose target escapes the library root. filepath.WalkDir
	// does not follow symlinks, so it is never emitted or probed (withinRoot is
	// the defense-in-depth second check).
	mustSymlink(t, "/etc/passwd", filepath.Join(root, "escape.mkv"))
	return root
}

// makeMedia generates a tiny probeable Matroska file at path via ffmpeg's lavfi
// testsrc (the same generator the base-scanner contract tests use). It t.Fatal's
// if ffmpeg fails or produces an empty file.
func makeMedia(t *testing.T, path string) {
	t.Helper()
	err := exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration=0.3:size=16x16:rate=10",
		"-loglevel", "error",
		"-y",
		filepath.Clean(path),
	).Run()
	if err != nil {
		t.Fatalf("ffmpeg generate %s: %v", filepath.Base(path), err)
	}
	if info, statErr := os.Stat(path); statErr != nil || info.Size() == 0 {
		t.Fatalf("media fixture %s not generated (empty)", filepath.Base(path))
	}
}

func mustMkdir(t *testing.T, path string) {
	t.Helper()
	if err := os.MkdirAll(path, 0o755); err != nil {
		t.Fatalf("mkdir %s: %v", path, err)
	}
}

func mustWrite(t *testing.T, path string, data []byte) {
	t.Helper()
	if err := os.WriteFile(path, data, 0o644); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
}

func mustSymlink(t *testing.T, target, link string) {
	t.Helper()
	if err := os.Symlink(target, link); err != nil {
		t.Fatalf("symlink %s -> %s: %v", link, target, err)
	}
}

// startServer launches the real mellifera server subprocess configured for the
// test: a temp data dir + temp SQLite DB, the given admin token, the built
// base-scanner + tv-parser + image-enricher binaries plus the three serial-suite
// plugin binaries (serialPluginBins), and a random free port. It blocks until the
// server answers HTTP, then returns the base URL. The server is stopped (SIGINT
// with a SIGKILL fallback) and its combined log is dumped in a cleanup on exit.
//
// The plugins are built and pointed at explicitly (MELLIFERA_* env) so the
// harness is HERMETIC: the server loads every seeded module at startup
// (mandatory — fatalOn if absent) and must not fall back to the non-hermetic
// repo-relative bin/ artifacts, which only resolve when the tests happen to run
// from the module root. All six plugins are real go-plugin subprocesses on the
// hot path (no in-process fakes).
func startServer(t *testing.T, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, token string) string {
	t.Helper()
	addr := net.JoinHostPort("127.0.0.1", freePort(t))
	dataDir := filepath.Join(tmp, "data")
	serialScannerBin, serialParserBin, frameGrabberBin := serialPluginBins(t, tmp)

	srv := exec.Command(serverBin)
	srv.Env = append(os.Environ(),
		"MELLIFERA_DATA_DIR="+dataDir,
		"MELLIFERA_ADMIN_TOKEN="+token,
		"MELLIFERA_BASE_SCANNER="+scannerBin,
		"MELLIFERA_TV_PARSER="+tvParserBin,
		"MELLIFERA_IMAGE_ENRICHER="+imageEnricherBin,
		"MELLIFERA_SERIAL_SCANNER="+serialScannerBin,
		"MELLIFERA_SERIAL_PARSER="+serialParserBin,
		"MELLIFERA_FRAME_GRABBER="+frameGrabberBin,
		"MELLIFERA_SHIKIMORI="+shikimoriBin(t, tmp),
		"MELLIFERA_LISTEN="+addr,
	)
	var log strings.Builder
	srv.Stdout = &log
	srv.Stderr = &log
	if err := srv.Start(); err != nil {
		t.Fatalf("start server: %v", err)
	}
	baseURL := "http://" + addr
	t.Cleanup(func() { stopServer(t, srv, &log) })
	if !waitForReady(baseURL) {
		t.Fatalf("server not ready at %s within %s; log:\n%s", baseURL, readinessDial, log.String())
	}
	return baseURL
}

// stopServer gracefully stops the server (SIGINT — the server's
// signal.NotifyContext path runs srv.Shutdown + plugin.Manager.Stop + store.Close)
// with a SIGKILL fallback if it does not exit within shutdownGrace. The combined
// log is always dumped (Go shows t.Logf output for failed tests).
func stopServer(t *testing.T, srv *exec.Cmd, log *strings.Builder) {
	t.Helper()
	// Wait joins the process AND its stdout/stderr copier goroutines (which write
	// log). The log dump MUST come after Wait returns, otherwise log.String() races
	// the pipe copiers (a real data race surfaced once -race covered the root
	// integration tests). If Wait already returned (ProcessState set) a second Wait
	// returns the cached state immediately; the copiers were joined by the first.
	if srv.ProcessState == nil {
		_ = srv.Process.Signal(os.Interrupt)
	}
	done := make(chan struct{})
	go func() { _ = srv.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(shutdownGrace):
		_ = srv.Process.Kill()
		<-done
	}
	t.Logf("server log:\n%s", log.String())
}

// waitForReady polls the server until it answers any HTTP request — even a 401
// from the admin middleware counts as "up". Returns false if the dial deadline
// passes with no answer.
func waitForReady(baseURL string) bool {
	probe := &http.Client{Timeout: time.Second}
	deadline := time.Now().Add(readinessDial)
	for time.Now().Before(deadline) {
		resp, err := probe.Get(baseURL + "/api/v1/items?library=0")
		if err == nil {
			resp.Body.Close()
			return true
		}
		time.Sleep(probeInterval)
	}
	return false
}

// freePort asks the OS for a free TCP port by briefly binding to :0.
func freePort(t *testing.T) string {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("free port: %v", err)
	}
	defer l.Close()
	return fmt.Sprintf("%d", l.Addr().(*net.TCPAddr).Port)
}

// doRequest performs one HTTP request with the admin bearer token, JSON-encoding
// body when non-nil and decoding the response into out when non-nil. It returns
// the HTTP status. Centralizing the exchange keeps the test free of repeated
// client/decode boilerplate (dupl budget). Diagnostics on a non-2xx come from
// the captured server log dumped by the cleanup, not from a parsed error body.
func doRequest(t *testing.T, c *http.Client, method, url, token string, body, out any) int {
	t.Helper()
	var req *http.Request
	var err error
	if body != nil {
		buf, merr := json.Marshal(body)
		if merr != nil {
			t.Fatalf("marshal body: %v", merr)
		}
		req, err = http.NewRequest(method, url, strings.NewReader(string(buf)))
	} else {
		req, err = http.NewRequest(method, url, nil)
	}
	if err != nil {
		t.Fatalf("new request %s %s: %v", method, url, err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("do %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	if out != nil {
		_ = json.NewDecoder(resp.Body).Decode(out)
	}
	return resp.StatusCode
}

// createLibrary POSTs a TV library rooted at rootPath and returns its id.
type createLibraryRequest struct {
	ModuleID    string `json:"module_id"`
	RootPath    string `json:"root_path"`
	DisplayName string `json:"display_name"`
}

type libraryResponse struct {
	ID int64 `json:"id"`
}

func createLibrary(t *testing.T, c *http.Client, baseURL, token, root string) int64 {
	t.Helper()
	body := createLibraryRequest{ModuleID: "tv", RootPath: root, DisplayName: "Integration TV"}
	var resp libraryResponse
	status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", token, body, &resp)
	if status != http.StatusCreated {
		t.Fatalf("create library: status %d, want 201", status)
	}
	return resp.ID
}

type scanResponse struct {
	LibraryID  int64    `json:"library_id"`
	Discovered int      `json:"discovered"`
	Persisted  int      `json:"persisted"`
	Warnings   []string `json:"warnings"`
}

// scanLibrary triggers a synchronous scan and returns its result.
func scanLibrary(t *testing.T, c *http.Client, baseURL, token string, id int64) scanResponse {
	t.Helper()
	var resp scanResponse
	url := fmt.Sprintf("%s/api/v1/libraries/%d/scan", baseURL, id)
	status := doRequest(t, c, http.MethodPost, url, token, nil, &resp)
	if status != http.StatusOK {
		t.Fatalf("scan library %d: status %d, want 200", id, status)
	}
	return resp
}

type itemDTO struct {
	ID           string          `json:"id"`
	RelativePath string          `json:"relative_path"`
	MediaType    string          `json:"media_type"`
	Document     json.RawMessage `json:"document"`
	Status       string          `json:"status"`
}

type itemsResponse struct {
	Items []itemDTO `json:"items"`
}

// listItems lists all items for a library (up to the 200-item cap).
func listItems(t *testing.T, c *http.Client, baseURL, token string, id int64) []itemDTO {
	t.Helper()
	var resp itemsResponse
	url := fmt.Sprintf("%s/api/v1/items?library=%d&limit=200", baseURL, id)
	status := doRequest(t, c, http.MethodGet, url, token, nil, &resp)
	if status != http.StatusOK {
		t.Fatalf("list items lib %d: status %d, want 200", id, status)
	}
	return resp.Items
}

// indexByPath maps each item by its library-relative path so assertions are
// order-independent (QueryItems orders by id, which is hash-derived).
func indexByPath(t *testing.T, items []itemDTO) map[string]itemDTO {
	t.Helper()
	out := make(map[string]itemDTO, len(items))
	for _, it := range items {
		if _, dup := out[it.RelativePath]; dup {
			t.Fatalf("duplicate item for relative path %q", it.RelativePath)
		}
		out[it.RelativePath] = it
	}
	return out
}

// itemDoc is the navigated slice of the architecture §3.1 document. The parsed
// fields come from filename heuristics (ffprobe-independent); ffprobe is the
// verbatim probe blob (absent when the file could not be probed — AC-6).
type itemDoc struct {
	FileID        string          `json:"file_id"`
	ModuleType    string          `json:"module_type"`
	SchemaVersion int             `json:"schema_version"`
	Parsed        map[string]any  `json:"parsed"`
	Ffprobe       json.RawMessage `json:"ffprobe"`
}

func parseDoc(t *testing.T, it itemDTO) itemDoc {
	t.Helper()
	var doc itemDoc
	if err := json.Unmarshal(it.Document, &doc); err != nil {
		t.Fatalf("unmarshal document for %q: %v (doc=%s)", it.RelativePath, err, it.Document)
	}
	return doc
}

func docString(m map[string]any, key string) string {
	s, _ := m[key].(string)
	return s
}

// docNumber reads a numeric parsed field; -1 signals absence (so a missing
// season is distinguishable from a real 0).
func docNumber(m map[string]any, key string) int64 {
	f, ok := m[key].(float64)
	if !ok {
		return -1
	}
	return int64(f)
}

func pathsOf(m map[string]itemDTO) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

// expectedItem is the reviewer-re-derivable BASE-field outcome for one fixture.
// After the Task 07 extraction base-scanner is media-type-agnostic: its parsed
// Struct carries the relative path + extension ONLY — no title/season/episode
// (the TV parse moved to the tv-parser plugin; full-pipeline re-assertion is the
// Task 11 golden).
type expectedItem struct {
	rel string // the fixture's library-relative path (echoed in parsed.relative_path)
	ext string // the parsed extension
}

// expectedParsedItems lists the base fields each fixture's parsed Struct MUST
// carry after the extraction: the relative path (echoed verbatim) + the
// extension. The TV-specific parse (title/season/episode/resolution/
// release_group) is now produced by the tv-parser plugin (Task 06) and asserted
// in its parser_test.go; the full discovery->tv-parser pipeline is re-asserted by
// the Task 11 golden. The Cyrillic fixture stays in the set to prove it is still
// discovered + base-identified (Cyrillic parse correctness lives in tv-parser).
var expectedParsedItems = []expectedItem{
	{rel: "Breaking Bad/Season 1/Breaking Bad S01E01.mkv", ext: ".mkv"},
	{rel: "Breaking Bad S01E02 1080p-EXAMPLE.mkv", ext: ".mkv"},
	{rel: "Игра престолов S01E01.mkv", ext: ".mkv"},
}

// assertParsedItems checks the media-type-agnostic base-field contract (AC-1
// post extraction) for every fixture.
func assertParsedItems(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, want := range expectedParsedItems {
		it, ok := byRel[want.rel]
		if !ok {
			t.Errorf("missing item for %q (have %v)", want.rel, pathsOf(byRel))
			continue
		}
		checkParsed(t, want, parseDoc(t, it))
	}
}

// checkParsed asserts the base-field contract (AC-1 extraction): parsed carries
// relative_path + extension and NO TV-specific fields, which now come from the
// tv-parser plugin (Task 06) via enrich.
func checkParsed(t *testing.T, want expectedItem, doc itemDoc) {
	t.Helper()
	if got := docString(doc.Parsed, "relative_path"); got != want.rel {
		t.Errorf("%q: parsed relative_path = %q, want %q", want.rel, got, want.rel)
	}
	if got := docString(doc.Parsed, "extension"); got != want.ext {
		t.Errorf("%q: parsed extension = %q, want %q", want.rel, got, want.ext)
	}
	// Structural/negative (AC-1 extraction): no TV fields leak from base-scanner.
	for _, bad := range []string{"title", "season", "episode"} {
		if _, ok := doc.Parsed[bad]; ok {
			t.Errorf("%q: parsed must not carry %q (TV parse extracted to tv-parser)", want.rel, bad)
		}
	}
	if doc.ModuleType != "tv" {
		t.Errorf("%q: module_type = %q, want tv", want.rel, doc.ModuleType)
	}
	// Documents copy the module row's schema_version — the tv seed moved to
	// v2 (frame-grabber binding), so tv items stamp 2.
	if doc.SchemaVersion != 2 {
		t.Errorf("%q: schema_version = %d, want 1", want.rel, doc.SchemaVersion)
	}
}

// assertAC1FfprobeBlobs checks the AC-1 ffprobe contract: the real media files
// carry a NON-EMPTY, valid-JSON ffprobe blob (proving real ffprobe ran through
// the subprocess pipeline). The top-level guard guarantees ffprobe is on PATH.
func assertAC1FfprobeBlobs(t *testing.T, byRel map[string]itemDTO) {
	t.Helper()
	for _, rel := range []string{
		"Breaking Bad/Season 1/Breaking Bad S01E01.mkv",
		"Breaking Bad S01E02 1080p-EXAMPLE.mkv",
		"Игра престолов S01E01.mkv",
	} {
		it, ok := byRel[rel]
		if !ok {
			t.Errorf("AC-1: %q not persisted; have %v", rel, pathsOf(byRel))
			continue
		}
		doc := parseDoc(t, it)
		if !json.Valid(doc.Ffprobe) || len(doc.Ffprobe) == 0 {
			t.Errorf("AC-1: %q ffprobe blob empty/invalid, want non-empty JSON (real ffprobe)", rel)
		}
	}
}

// assertSoftFailItem checks the AC-6 soft-fail contract: the zero-byte file is
// still persisted (identified without ffprobe) with an EMPTY ffprobe field.
func assertSoftFailItem(t *testing.T, byRel map[string]itemDTO, rel string) {
	t.Helper()
	it, ok := byRel[rel]
	if !ok {
		t.Fatalf("AC-6: %q not persisted (an unprobeable file must still be identified); have %v", rel, pathsOf(byRel))
	}
	if len(parseDoc(t, it).Ffprobe) != 0 {
		t.Errorf("AC-6: %q ffprobe field non-empty, want empty (soft-fail)", rel)
	}
}

// assertEscapeSkipped checks the AC-4 path-traversal contract: the escaping
// symlink produces NO persisted item and nothing outside the root is probed.
//
// Grounding note: filepath.WalkDir does not follow symlinks, so the escape is
// skipped silently — no warning surfaces in the scan result. The task spec's
// "escape -> skipped + warned" sub-claim is therefore not satisfiable by the
// implemented behavior; asserting a warning here would be false. The real AC-4
// invariant — "no file outside the configured root is ffprobed, read, or
// persisted" — IS asserted: the escape yields no item, and the only persisted
// items are the in-root fixtures (verified by the discovered/persisted counts
// and the per-item assertions above).
func assertEscapeSkipped(t *testing.T, byRel map[string]itemDTO, rel string) {
	t.Helper()
	if it, leaked := byRel[rel]; leaked {
		t.Fatalf("AC-4: escaping %q was persisted (relative_path=%s) — outside-root access", rel, it.RelativePath)
	}
}

// scanWarnedAboutFfprobe reports whether the scan warnings include an ffprobe
// soft-fail entry (the bad.mkv zero-byte file when ffprobe is present; or every
// file when ffprobe is absent — either way the AC-6 warning surfaces).
func scanWarnedAboutFfprobe(warnings []string) bool {
	for _, w := range warnings {
		if strings.Contains(w, "ffprobe") {
			return true
		}
	}
	return false
}
